var CAPACITY=3;
var bookings=$input.all().map(i=>i.json).filter(b=>!!b.date);
var confirmedCount={};
bookings.filter(b=>String(b.status||'').toLowerCase()==='confirmed').forEach(b=>{var id=b.slot_Id||b.slot_id||'';confirmedCount[id]=(confirmedCount[id]||0)+1;});
var pending=bookings.filter(b=>{var s=String(b.status||'').toLowerCase();return b.date&&(s===''||s==='pending');});
var pendingCount={};
pending.forEach(b=>{var id=b.slot_Id||b.slot_id||'';pendingCount[id]=(pendingCount[id]||0)+1;});
pending=pending.map(b=>{var id=b.slot_Id||b.slot_id||'';var conf=confirmedCount[id]||0;var pend=pendingCount[id]||0;var conflict=conf>=CAPACITY||(conf+pend)>CAPACITY;return Object.assign({},b,{slot_status:conflict?'taken':'available'});});
pending.sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.time).localeCompare(String(b.time)));
return [{json:{bookings:pending,count:pending.length}}];

